#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Force; 16] = [
        Force::const_new(1234.5, ForceUnit::Dyn),
        Force::const_new(1234.5, ForceUnit::GramForce),
        Force::const_new(1234.5, ForceUnit::KilogramForce),
        Force::const_new(1234.5, ForceUnit::TonneForce),
        Force::const_new(1234.5, ForceUnit::Newton),
        Force::const_new(1234.5, ForceUnit::Micronewton),
        Force::const_new(1234.5, ForceUnit::Millinewton),
        Force::const_new(1234.5, ForceUnit::Decanewton),
        Force::const_new(1234.5, ForceUnit::Kilonewton),
        Force::const_new(1234.5, ForceUnit::Meganewton),
        Force::const_new(1234.5, ForceUnit::Kilopond),
        Force::const_new(1234.5, ForceUnit::Poundal),
        Force::const_new(1234.5, ForceUnit::PoundForce),
        Force::const_new(1234.5, ForceUnit::KilopoundForce),
        Force::const_new(1234.5, ForceUnit::OunceForce),
        Force::const_new(1234.5, ForceUnit::ShortTonForce),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ForceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Force::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ForceUnit::ALL {
            assert_eq!(
                Force::const_new(v, unit).as_base().to_bits(),
                Force::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Force::from_base(v);
        let auto = q.auto_unit();
        assert_close(Force::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in ForceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(Force::from_base(0.0).auto_unit().unit, ForceUnit::Newton);
}

